/* @lc app=leetcode id=3862 lang=kotlin */ class Solution { fun smallestBalancedIndex(nums: IntArray): Int = nums.size.let { n -> nums.runningFold(0L) { a, b -> a + b }.let { pre -> nums.reversed().runningFold(1L) { p, x -> if (p > 1_000_000_000_000_000L / x) 1_000_000_000_000_000L else minOf(1_000_000_000_000_000L, p * x) }.reversed().let { suf -> (0 until n).firstOrNull { pre[it] == suf[it + 1] } ?: -1 } } } }